import React from 'react';

import ObstacleCategoryBadge from '@apps/Obstacles/components/ObstacleCategoryBadge/ObstacleCategoryBadge';
import { ObstacleIcon } from '@apps/Obstacles/components/ObstacleIcon/ObstacleIcon';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { formatAltitude } from '@helpers/formatHelper';
import PohAva from '@ui-kit/Ava';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { getObstacleTypeName } from '../../Obstacles/@resources/obstacles.resource';
import { IHikingObstacleWithObstacleListItem } from '../@types/hikingObstacles.types';

interface IHikingObstacleListItemProps {
  obstacleItem: IHikingObstacleWithObstacleListItem;
}

const HikingObstacleListItem: React.FC<IHikingObstacleListItemProps> = ({ obstacleItem }) => {
  return (
    <PohRow>
      <PohCol sm={6}>
        <PohRow>
          <PohCol sm={2} xs={3}>
            {obstacleItem.last_photo_preview ? (
              <PohAva
                colorize
                alt={obstacleItem.obstacle.name}
                width={50}
                src={obstacleItem.last_photo_preview}
              />
            ) : (
              <PohAva
                width={50}
                colorize
                alt={obstacleItem.obstacle.name}
                icon={<ObstacleIcon type={obstacleItem.obstacle.type} />}
              />
            )}
          </PohCol>
          <PohCol sm={10} xs={9}>
            <div>
              <h5 className="mb-0">
                <span>{getObstacleTypeName(obstacleItem.obstacle.type)}</span>{' '}
                {obstacleItem.obstacle.name}
              </h5>
              <small>{dateRangeToLocaleString(obstacleItem.date_in, obstacleItem.date_out)}</small>
            </div>
          </PohCol>
        </PohRow>
      </PohCol>
      <PohCol sm={6} className="text-sm-end">
        <small>{formatAltitude(obstacleItem.obstacle.altitude)}</small>
        &nbsp;
        <ObstacleCategoryBadge category={obstacleItem.obstacle.category} />
      </PohCol>
    </PohRow>
  );
};

export default HikingObstacleListItem;
